import {readFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {resolve,isAbsolute} from 'node:path';
import {pathToFileURL} from 'node:url';
import {runtimeDigest} from '../tests/lab/runtime-proof.mjs';

// Receipts are generated by the trusted local lead, never taken from an issue.
export function validateReviewArtifact(artifact, p) {
  // The configured schema has verdict/summary/findings. The reviewer must
  // include its binding inside the summary; outer lead assertions are not proof.
  const line = artifact?.summary?.split('\n')[0] || '';
  let binding;
  try { if (line.startsWith('OLED-REVIEW ')) binding=JSON.parse(line.slice(12)); } catch {}
  if (artifact?.verdict!=='accept' || !Array.isArray(artifact.findings) || !binding ||
      binding.sha!==p.sha || binding.base!==p.base || binding.tree!==p.tree ||
      binding.model!=='gpt-6-luna' || binding.profile!=='review' || binding.independent!==true)
    throw Error('Review artifact does not independently accept this exact candidate');
  return true;
}

export function validateReportGate(p) {
  const fail = message => { throw Error('Automatic release blocked: '+message); };
  if (p?.schema !== 'oled-auto-release-v2' || p.repo !== 'bc1224/oled-night') fail('wrong project or receipt schema');
  if (!/^[a-f0-9]{40}$/.test(p.sha || '') || !/^[a-f0-9]{40}$/.test(p.base || '') || p.sha===p.base) fail('missing exact candidate and base');
  if (!Number.isSafeInteger(p.issue) || p.issue<1) fail('missing issue number');
  const browsers=p.reproduction?.browsers;
  if (!Array.isArray(browsers) || browsers.length!==2 || ['Chrome','Firefox'].some(engine=>browsers.filter(b=>b.engine===engine).length!==1)) fail('retained Chrome and Firefox proof required');
  for (const browser of browsers) {
    if (typeof browser.check!=='string' || !browser.check.trim() || browser.check.length>300) fail('named matching bug assertion required');
    for (const stage of ['base','fixed']) {
      const proof=browser[stage];
      if (!proof || typeof proof.path!=='string' || !isAbsolute(proof.path) || !/^[a-f0-9]{64}$/.test(proof.hash || '')) fail('absolute retained proof path and digest required');
    }
  }
  if (!/^[a-z][a-z-]+$/.test(p.fixture || '')) fail('missing public regression fixture');
  if (!Array.isArray(p.files) || !p.files.length || p.files.some(f => !/^(?:content\.js|color-utils\.js|youtube-theme\.js|settings\.js|manifest\.json|CHANGELOG\.md|tests\/(?:e2e|lab)\/[-a-zA-Z0-9_./]+|docs\/lab\/[-a-zA-Z0-9_./]+)$/.test(f) || f.includes('..') || f.includes('/baselines/'))) fail('change outside runtime bug and test scope');
  if (p.permissionsChanged !== false || p.dependenciesChanged !== false) fail('permissions/dependencies changed');
  if (p.review?.verdict !== 'accept' || p.review?.sha !== p.sha || p.review?.independent !== true || p.review?.profile !== 'review' || p.review?.model !== 'gpt-6-luna' || !/^[a-f0-9]{64}$/.test(p.review?.receiptHash || '')) fail('independent exact-source acceptance with authorized reviewer required');
  if (p.ci?.sha!==p.sha || p.ci?.conclusion!=='success' || !Number.isSafeInteger(p.ci?.runId) || p.ci.runId<1) fail('successful exact-source CI required');
  return true;
}

export function validateReproductionArtifacts(p, {
  read=readFileSync,
  sourceDigest=sha=>runtimeDigest(file=>execFileSync('git',['show',sha+':'+file],{maxBuffer:8*1024*1024}))
}={}) {
  validateReportGate(p);
  const digests={base:sourceDigest(p.base),fixed:sourceDigest(p.sha)};
  for (const browser of p.reproduction.browsers) for (const stage of ['base','fixed']) {
    const proof=browser[stage], bytes=read(proof.path);
    if (createHash('sha256').update(bytes).digest('hex')!==proof.hash) throw Error('Reproduction artifact digest mismatch');
    const report=JSON.parse(bytes);
    if (report.engine!==browser.engine || report.sha!==(stage==='base'?p.base:p.sha) || report.runtimeHash!==digests[stage] || report.completed!==true || report.candidate===true)
      throw Error('Reproduction must complete against the exact packaged source');
    if (!Array.isArray(report.checks) || !report.checks.length || report.checks.some(c=>typeof c.name!=='string' || typeof c.ok!=='boolean')) throw Error('Malformed browser assertions');
    const fixture=report.checks.filter(c=>c.fixture===p.fixture);
    const activation=fixture.filter(c=>c.kind==='activation');
    const assertion=fixture.filter(c=>c.kind==='assertion' && c.name===browser.check);
    if (!activation.length || activation.some(c=>!c.ok) || assertion.length!==1 || assertion[0].ok!==(stage==='fixed')) throw Error('Matching active-runtime bug failure and fixed pass required');
    if (stage==='fixed' && report.checks.some(c=>!c.ok)) throw Error('Fixed browser report still fails');
    // Infrastructure failures are never reproduction, even alongside a bug.
    if (report.checks.some(c=>!c.ok && (c.kind!=='assertion' || !c.fixture))) throw Error('Unverified infrastructure or unclassified failure');
  }
  return true;
}

if (process.argv[1] && import.meta.url===pathToFileURL(resolve(process.argv[1])).href) {
  const p=JSON.parse(readFileSync(process.argv[2], 'utf8'));
  validateReproductionArtifacts(p);
  if (execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim()!==p.sha) throw Error('Receipt is not current HEAD');
  const files=execFileSync('git',['diff','--name-only',p.base,p.sha],{encoding:'utf8'}).trim().split('\n').filter(Boolean).sort();
  if (JSON.stringify(files)!==JSON.stringify([...p.files].sort())) throw Error('Changed-file receipt mismatch');
  const base=JSON.parse(execFileSync('git',['show',p.base+':manifest.json'],{encoding:'utf8'}));
  const manifest=JSON.parse(readFileSync('manifest.json','utf8'));
  const a={...base},b={...manifest}; delete a.version;delete b.version;
  if (JSON.stringify(a)!==JSON.stringify(b) || base.version===manifest.version) throw Error('Only an incremented manifest version is permitted');
  const v=version=>version.split('.').reduce((total,n)=>total*1000+Number(n),0);
  if (v(manifest.version)<=v(base.version)) throw Error('Version must increase');
  const review=JSON.parse(readFileSync(p.review.receiptPath,'utf8'));
  const digest=createHash('sha256').update(readFileSync(p.review.receiptPath)).digest('hex');
  if (digest!==p.review.receiptHash) throw Error('Review artifact digest mismatch');
  const tree=execFileSync('git',['rev-parse',p.sha+'^{tree}'],{encoding:'utf8'}).trim();
  validateReviewArtifact(review,{...p,tree});
  const run=JSON.parse(execFileSync('gh',['api','repos/bc1224/oled-night/actions/runs/'+p.ci.runId],{encoding:'utf8'}));
  if (run.head_sha!==p.sha || run.conclusion!=='success' || run.name!=='Tests' || run.head_branch!=='main' || run.event!=='push') throw Error('Provider CI receipt mismatch');
  const issue=JSON.parse(execFileSync('gh',['issue','view',String(p.issue),'--repo','bc1224/oled-night','--json','state,labels'],{encoding:'utf8'}));
  if (issue.state!=='OPEN' || !issue.labels.some(l=>l.name==='oled-report')) throw Error('Issue is not an open labelled report');
  const {cases}=await import('../tests/lab/catalog.mjs');
  if (!cases.some(c=>c.id===p.fixture)) throw Error('Fixture missing from public catalog');
  // Existing gate independently checks the retained exact-source lab artifact.
  execFileSync(process.execPath,['tools/verify-release-gate.mjs'],{stdio:'inherit',env:{...process.env,GITHUB_SHA:p.sha}});
  console.log('PASS automatic report release gate: '+p.sha);
}
